    "message": "{\"Sketch\": {\"sketchPoints\": \"Returns the sketch points collection associated with this sketch.\\nThis provides access to the existing sketch points and supports\\nthe creation of new sketch points.\"}, \"Occurrences\": {\"addExistingComponent\": \"\\nMethod that creates a new occurrence using an existing component. This is the equivalent\\nof copying and pasting an occurrence in the user interface.\\ncomponent : The existing component to create a new occurrence of.\\ntransform : A transform that defines the location for the new occurrence\\nReturns the newly created occurrence or null if the creation failed.\\n\"}, \"AsBuiltJoint\": {\"jointMotion\": \"Returns a JointMotion object that defines the motion relationship between the two geometries.\", \"geometry\": \"Specifies the position of the joint. Getting this property will return null and\\nsetting it will be ignored in the case where the joint motion is rigid.\\nTo set this property, you need to position the timeline marker to immediately before this as-built joint.\\nThis can be accomplished using the following code: thisAsBuiltJoint.timelineObject.rollTo(True)\", \"isSuppressed\": \"Gets and sets if this as-built joint is suppressed.\"}, \"AsBuiltJoints\": {\"add\": \"\\nCreates a new as-built joint.\\ninput : An AsBuiltJointInput object that was created using the AsBuiltJoints.createInput method and then fully defined\\nusing the properties and methods on the AsBuiltJointInput object.\\nReturns the new AsBuiltJoint object or null in the case of failure.\\n\"}, \"RigidGroups\": {\"add\": \"\\nCreates a new rigid group.\\noccurrences : An ObjectCollection containing the occurrences to use in creating the rigid group.\\nincludeChildren : Boolean indicating if the children of the input occurrences should be included in the rigid group.\\nReturns the new RigidGroup object or null in the case of failure.\\n\"}, \"SketchPoints\": {\"add\": \"\\nCreates a point at the specified location. This is the equivalent\\nof creating a sketch point using the Point command in the user\\ninterface and will create a visible point in the graphics window.\\npoint : The coordinate location to create the sketch point.\\nReturns the new sketch point or null if the creation fails.\\n\"}, \"JointLimits\": {\"minimumValue\": \"The minimum value of the value. This is in either centimeters\\nor radians depending on if the joint value this is associated with\\ndefines a distance or an angle.\", \"maximumValue\": \"The maximum value of the value. This is in either centimeters\\nor radians depending on if the joint value this is associated with\\ndefines a distance or an angle.\", \"isMinimumValueEnabled\": \"Gets and sets whether the minimum joint limit is enabled or not.\", \"isMaximumValueEnabled\": \"Gets and sets whether the maximum joint limit is enabled or not.\"}, \"appearance_props\": [{\"id\": \"interior_model\", \"type\": \"adsk::core::IntegerProperty\", \"name\": \"\\uc7ac\\ub8cc \\uc720\\ud615\"}, {\"id\": \"opaque_albedo\", \"type\": \"adsk::core::ColorProperty\", \"name\": \"\\uc0c9\\uc0c1\"}, {\"id\": \"opaque_albedo_colorspace\", \"type\": \"adsk::core::ChoiceProperty\", \"name\": \"\\uc0c9\\uc0c1 \\uacf5\\uac04\"}, {\"id\": \"opaque_albedo_urn\", \"type\": \"adsk::core::StringProperty\", \"name\": \"URN\"}, {\"id\": \"opaque_emission\", \"type\": \"adsk::core::BooleanProperty\", \"name\": \"\\ubc29\\uc0ac\"}, {\"id\": \"opaque_f0\", \"type\": \"adsk::core::FloatProperty\", \"name\": \"\\ubc18\\uc0ac\\uc728\"}, {\"id\": \"opaque_f0_urn\", \"type\": \"adsk::core::StringProperty\", \"name\": \"URN\"}, {\"id\": \"opaque_luminance\", \"type\": \"adsk::core::FloatProperty\", \"name\": \"\\ubc29\\uc0ac \\uad11\\ub3c4\"}, {\"id\": \"opaque_luminance_modifier\", \"type\": \"adsk::core::ColorProperty\", \"name\": \"\\uad11\\ub3c4 \\ubc30\\uc728\"}, {\"id\": \"opaque_luminance_modifier_colorspace\", \"type\": \"adsk::core::ChoiceProperty\", \"name\": \"\\uc0c9\\uc0c1 \\uacf5\\uac04\"}, {\"id\": \"opaque_luminance_modifier_urn\", \"type\": \"adsk::core::StringProperty\", \"name\": \"URN\"}, {\"id\": \"opaque_mfp\", \"type\": \"adsk::core::FloatProperty\", \"name\": \"\\uae4a\\uc774\"}, {\"id\": \"opaque_mfp_modifier\", \"type\": \"adsk::core::ColorProperty\", \"name\": \"\\uac00\\uc911\\uce58\"}, {\"id\": \"opaque_mfp_modifier_colorspace\", \"type\": \"adsk::core::ChoiceProperty\", \"name\": \"\\uc0c9\\uc0c1 \\uacf5\\uac04\"}, {\"id\": \"opaque_mfp_modifier_urn\", \"type\": \"adsk::core::StringProperty\", \"name\": \"URN\"}, {\"id\": \"opaque_translucency\", \"type\": \"adsk::core::BooleanProperty\", \"name\": \"\\ubc18\\ud22c\\uba85\\ub3c4\"}, {\"id\": \"surface_albedo\", \"type\": \"adsk::core::ColorProperty\", \"name\": \"\\uc0c9\\uc0c1\"}, {\"id\": \"surface_albedo_colorspace\", \"type\": \"adsk::core::ChoiceProperty\", \"name\": \"\\uc0c9\\uc0c1 \\uacf5\\uac04\"}, {\"id\": \"surface_albedo_urn\", \"type\": \"adsk::core::StringProperty\", \"name\": \"URN\"}, {\"id\": \"surface_anisotropy\", \"type\": \"adsk::core::FloatProperty\", \"name\": \"\\uc774\\ubc29\\uc131\"}, {\"id\": \"surface_anisotropy_urn\", \"type\": \"adsk::core::StringProperty\", \"name\": \"URN\"}, {\"id\": \"surface_cutout\", \"type\": \"adsk::core::AppearanceTextureProperty\", \"name\": \"\\uc774\\ubbf8\\uc9c0\"}, {\"id\": \"surface_cutout_urn\", \"type\": \"adsk::core::StringProperty\", \"name\": \"URN\"}, {\"id\": \"surface_ndf_type\", \"type\": \"adsk::core::ChoiceProperty\", \"name\": \"NDF\"}, {\"id\": \"surface_normal\", \"type\": \"adsk::core::AppearanceTextureProperty\", \"name\": \"\\uc774\\ubbf8\\uc9c0\"}, {\"id\": \"surface_normal_urn\", \"type\": \"adsk::core::StringProperty\", \"name\": \"URN\"}, {\"id\": \"surface_rotation\", \"type\": \"adsk::core::FloatProperty\", \"name\": \"\\ud68c\\uc804\"}, {\"id\": \"surface_rotation_urn\", \"type\": \"adsk::core::StringProperty\", \"name\": \"URN\"}, {\"id\": \"surface_roughness\", \"type\": \"adsk::core::Floa